enum class State { idle, waiting, done, cancelled };
struct Machine {
    State state = State::idle;
    std::uint64_t generation = 0;
    void start() { ++generation; state = State::waiting; }
    void cancel() { if (state == State::waiting) state = State::cancelled; }
    void complete(std::uint64_t id) {
        if (id == generation && state == State::waiting) state = State::done;
    }
};

