bool read_be16(const std::uint8_t* data, std::size_t size,
               std::size_t offset, std::uint16_t& out) {
    if (offset > size || size - offset < 2) return false;
    out = static_cast<std::uint16_t>(
        (std::uint16_t(data[offset]) << 8) | data[offset + 1]);
    return true;
}

